import numpy as np
from sklearn.preprocessing import MinMaxScaler
import pandas as pd

def task_func(df: pd.DataFrame) -> pd.DataFrame:
    if df.empty:
        raise ValueError("The DataFrame is empty.")

    if df.isna().any().any():
        raise ValueError("The DataFrame contains NaN values.")

    if not all(pd.api.types.is_numeric_dtype(dtype) for dtype in df.dtypes):
        raise TypeError("The DataFrame contains non-numeric data types.")

    cumsum_df = df.cumsum()

    scaler = MinMaxScaler()
    normalized_data = scaler.fit_transform(cumsum_df)

    return pd.DataFrame(normalized_data, index=df.index, columns=df.columns)
